pub fn read(io: std.Io) !Topology {
    const lines = try readLines(io, "input/topology.txt");
    var ases: std.ArrayList(AutonomousSystem) = .empty;
    for (lines) |line| {
        const f = words(line);
        if (eq(f[0], "AS")) append(AutonomousSystem, &ases, .{ .number = number(f[1]), .router_id = addressValue(f[2]) });
    }
    std.mem.sort(AutonomousSystem, ases.items, {}, struct {
        fn less(_: void, a: AutonomousSystem, b: AutonomousSystem) bool {
            return a.number < b.number;
        }
    }.less);
    var out: Topology = .{ .ases = ases.items, .links = &.{}, .initial = &.{} };
    var links: std.ArrayList(Link) = .empty;
    var initial: std.ArrayList(Initial) = .empty;
    for (lines) |line| {
        const f = words(line);
        if (eq(f[0], "LINK")) append(Link, &links, .{ .name = f[1], .first = out.asIndex(number(f[2])),
             .second = out.asIndex(number(f[3])), .peer = eq(f[4], "P2P"), .delay = number(f[5]),
             .mrai = number(f[6]) }) else if (eq(f[0], "PREFIX")) append(Initial, &initial,
             .{ .owner = out.asIndex(number(f[1])), .prefix = parsePrefix(f[2]), .origin = parseOrigin(f[3]),
             .communities = f[4..] });
    }
    out.links = links.items;
    out.initial = initial.items;
    return out;
}
    pub fn applied(self: *Policies, direction: Direction, owner: usize, link: t.Link, prefix: t.Prefix,
         path: []const usize, communities: []const u32) ?usize {
        for (self.rules, 0..) |rule, index| if (rule.direction == direction and self.matches(rule,
             owner, link, prefix, path, communities)) return index;
        return null;
    }
pub fn read(io: std.Io, network: *const t.Topology) !Policies {
    var lists: std.ArrayList(ListEntry) = .empty;
    var rules: std.ArrayList(Rule) = .empty;
    for (try t.readLines(io, "input/policies.txt")) |line| {
        const f = t.words(line);
        if (t.eq(f[0], "PLIST")) {
            const prefix = t.parsePrefix(f[3]);
            var low = prefix.length;
            var high = prefix.length;
            var i: usize = 4;
            while (i < f.len) : (i += 2) {
                if (t.eq(f[i], "GE")) {
                    low = t.u(t.number(f[i + 1]));
                    high = 32;
                } else high = t.u(t.number(f[i + 1]));
            }
            t.append(ListEntry, &lists, .{ .name = f[1], .permit = t.eq(f[2], "PERMIT"), .prefix = prefix,
                 .low = low, .high = high });
            continue;
        }
        var conditions: std.ArrayList(Condition) = .empty;
        var actions: std.ArrayList(Action) = .empty;
        var i: usize = 6;
        while (!t.eq(f[i], "THEN")) : (i += 2) {
            var condition: Condition = .{ .kind = .prefix };
            const kind = f[i];
            const value = f[i + 1];
            if (t.eq(kind, "PREFIX")) condition.name = value else if (t.eq(kind, "CONTAINS") or t.eq(kind,
                 "ORIGINAS")) {
                condition.kind = if (t.eq(kind, "CONTAINS")) .contains else .origin_as;
                var owner_index = network.ases.len;
                for (network.ases, 0..) |owner, index| if (owner.number == t.number(value)) {
                    owner_index = index;
                    break;
                };
                condition.value = t.n(owner_index);
            } else if (t.eq(kind, "LENGTH")) {
                const bounds = t.split(value, '-');
                condition = .{ .kind = .length, .value = t.number(bounds[0]), .high = t.number(bounds[1]) };
            } else condition = .{ .kind = .community, .value = parseCommunity(value) };
            t.append(Condition, &conditions, condition);
        }
        i += 1;
        while (i < f.len) {
            const name = f[i];
            i += 1;
            var action: Action = .{ .kind = .deny };
            if (t.eq(name, "DENY")) action.kind = .deny else if (t.eq(name, "ALLOW")) action.kind = .allow else {
                const kinds = [_]@FieldType(Action, "kind"){ .local_pref, .med, .prepend, .add, .remove };
                const names = [_][]const u8{ "LOCALPREF", "MED", "PREPEND", "ADD", "REMOVE" };
                for (names, kinds) |word, kind| if (t.eq(name, word)) {
                    action.kind = kind;
                };
                action.value = if (action.kind == .add or action.kind == .remove) parseCommunity(f[i]) else t.number(f[i]);
                i += 1;
            }
            t.append(Action, &actions, action);
        }
        const target_neighbor: ?usize = if (f[5][0] >= '0' and f[5][0] <= '9') network.asIndex(t.number(f[5])) else null;
        t.append(Rule, &rules, .{ .name = f[1], .active = t.eq(f[2], "ON"), .owner = network.asIndex(t.number(f[3])),
             .direction = if (t.eq(f[4], "IMPORT")) .import_route else .export_route, .target = f[5],
             .target_neighbor = target_neighbor, .conditions = conditions.items, .actions = actions.items });
    }
    return .{ .lists = lists.items, .rules = rules.items };
}
    pub fn send(self: *MessageQueue, time: i64, sender: usize, receiver: usize, index: usize,
         prefix: usize, content: ?*const d.Attribute, network: *const t.Topology) Message {
        self.serial += 1;
        const message: Message = .{ .serial = self.serial, .sender = sender, .receiver = receiver,
             .link = index, .prefix = prefix, .content = content, .arrival = time + network.links[index].delay };
        self.push(message);
        return message;
    }
pub fn readEvents(io: std.Io) ![]const Event {
    var out: std.ArrayList(Event) = .empty;
    t.append(Event, &out, .{ .time = 0, .text = "INITIAL", .fields = &.{"INITIAL"}, .kind = "INITIAL" });
    for (try t.readLines(io, "input/events.txt")) |line| {
        const separator = std.mem.indexOfScalar(u8, line, ' ') orelse unreachable;
        const text = line[separator + 1 ..];
        const fields = t.words(text);
        const kind = if (t.eq(fields[0], "LINK") or t.eq(fields[0], "POLICY")) t.fmt("{s}_{s}",
             .{ fields[0], fields[1] }) else fields[0];
        t.append(Event, &out, .{ .time = t.number(line[0..separator]), .text = text, .fields = fields, .kind = kind });
    }
    return out.items;
}
pub fn readParams(io: std.Io, network: *const t.Topology) !Params {
    const lines = try t.readLines(io, "input/params.txt");
    const defaults = t.words(lines[0]);
    var traces: std.ArrayList(Trace) = .empty;
    for (lines[2..]) |line| {
        const f = t.words(line);
        t.append(Trace, &traces, .{ .source = network.asIndex(t.number(f[1])), .address = f[2],
             .value = t.addressValue(f[2]) });
    }
    return .{ .defaults = .{ t.number(defaults[1]), t.number(defaults[2]), t.number(defaults[3]) },
         .stepcap = t.number(t.words(lines[1])[1]), .traces = traces.items };
}
